sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    // 1. 防止加载时触发，或日期被清空时触发
    if (isLoading || newValue === '') {
        return;
    }

    // 2. 定义我们要设置的时间字段名称
    var timeFieldName = 'leave_time_start';

    // 3. 获取当前时间字段的值
    // 注意：对于 Time 字段，g_form.getValue 通常返回 "HH:mm:ss" 格式的字符串
    var currentTime = g_form.getValue(timeFieldName);

    // 4. 逻辑判断：
    // 如果当前没有时间值，或者你想强制每次改日期都重置为 09:00，
    // 则直接设置。否则保持原样。

    // 方案 A: 如果你想每次改日期都把时间重置为 09:00:00
    // g_form.setValue(timeFieldName, '09:00:00');

    // 方案 B (推荐): 保持当前选择的时间，但确保格式正确
    if (!currentTime) {
        // 如果时间是空的，给它一个默认值
        g_form.setValue(timeFieldName, '09:00:00');
    } else {
        // 如果已经有时间（比如用户选了 14:00），我们确保它格式正确。
        // 通常不需要额外操作，除非你要处理时区。
        // 这里我们什么都不做，只是确保不报错。

        // 调试：可以在控制台看看取出的值是什么
        // console.log("Current time is: " + currentTime);
    }
}
